package sash

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"

	"github.com/afterdarksys/sahinit/internal/fail"
)

// testdata/sash-grant-vectors.json was generated by sash's own
// internal/grant (Sign, Message, Verify, EnvDenied, EnvName) at f28285b on
// feat/init-phase1; see "Decisions made during the build" in
// docs/design/sash-services-1.md. The same file belongs in sash's testdata.
type grantVectors struct {
	Source    string          `json:"source"`
	FleetPub  string          `json:"fleet_pub"`
	Now       int64           `json:"now"`
	Message   string          `json:"message"`
	Vectors   []grantVector   `json:"vectors"`
	EnvNames  []string        `json:"env_names"`
	EnvDenied map[string]bool `json:"env_denied"`
	EnvForm   map[string]bool `json:"env_form"`
}

type grantVector struct {
	Name string `json:"name"`
	Doc  string `json:"doc"`
	Want string `json:"want"`
}

func loadVectors(t *testing.T) grantVectors {
	t.Helper()
	raw, err := os.ReadFile("testdata/sash-grant-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v grantVectors
	if err := json.Unmarshal(raw, &v); err != nil || v.Source == "" || len(v.Vectors) == 0 {
		t.Fatalf("vectors: %v", err)
	}
	return v
}

func fleetOf(t *testing.T, v grantVectors) ed25519.PublicKey {
	t.Helper()
	k, err := hex.DecodeString(v.FleetPub)
	if err != nil || len(k) != ed25519.PublicKeySize {
		t.Fatal("fleet key")
	}
	return k
}

func TestGrantGoldenVectors(t *testing.T) {
	v := loadVectors(t)
	fleet := fleetOf(t, v)
	for _, c := range v.Vectors {
		g, err := VerifyGrant([]byte(c.Doc), fleet, v.Now)
		got := "ok"
		if err != nil {
			got = fail.Token(err)
		}
		if got != c.Want {
			t.Errorf("%s: %s, sash says %s", c.Name, got, c.Want)
		}
		if c.Name == "valid" && err == nil {
			msg, merr := Message(g)
			if merr != nil || string(msg) != v.Message {
				t.Errorf("message differs from sash's:\n%s\n%s", msg, v.Message)
			}
			if g.Service != "nginx" || g.Serial != 7 || g.User != "www" || !g.AllowsExec("/usr/sbin/nginx") || g.AllowsExec("/usr/sbin") {
				t.Errorf("grant %+v", g)
			}
		}
	}
}

func TestEnvTableMatchesSash(t *testing.T) {
	v := loadVectors(t)
	for _, n := range v.EnvNames {
		if EnvDenied(n) != v.EnvDenied[n] {
			t.Errorf("%s: denied %v, sash says %v", n, EnvDenied(n), v.EnvDenied[n])
		}
		if EnvName.MatchString(n) != v.EnvForm[n] {
			t.Errorf("%s: form %v, sash says %v", n, !v.EnvForm[n], v.EnvForm[n])
		}
	}
	// Every name on sahinit's table is in the vector, so a name added on
	// one side only is caught.
	listed := map[string]bool{}
	for _, n := range v.EnvNames {
		listed[n] = true
	}
	for n := range envDenied {
		if !listed[n] {
			t.Errorf("%s is denied here but not in sash's vector", n)
		}
	}
	g := Grant{EnvNames: []string{"PORT", "LD_PRELOAD", "GIT_DIR", "PATH", "lower"}}
	if !g.AllowsEnv("PORT") || !g.AllowsEnv("PATH") || g.AllowsEnv("LD_PRELOAD") || g.AllowsEnv("GIT_DIR") || g.AllowsEnv("HOME") || g.AllowsEnv("lower") {
		t.Fatal("env gates")
	}
}

// testFleet is a deterministic fleet key for tests that sign their own
// grants and floors.
func testFleet(label string) ed25519.PrivateKey {
	seed := sha256.Sum256([]byte(label))
	return ed25519.NewKeyFromSeed(seed[:])
}

func TestGrantRefusals(t *testing.T) {
	fleet := testFleet("fleet")
	other := testFleet("other")
	base := SampleGrant("app", "app", "app")
	sign := func(g Grant, k ed25519.PrivateKey) []byte {
		doc, err := SignGrant(g, k)
		if err != nil {
			t.Fatal(err)
		}
		return doc
	}
	pub := fleet.Public().(ed25519.PublicKey)
	if _, err := VerifyGrant(sign(base, fleet), pub, 1_700_000_000); err != nil {
		t.Fatal(err)
	}
	for name, c := range map[string]struct {
		doc  []byte
		want string
	}{
		"other key": {sign(base, other), "grant_bad_sig"},
		"empty":     {nil, "grant_missing"},
		"oversize":  {make([]byte, MaxGrant+1), "grant_bad_shape"},
		"trailing":  {append(sign(base, fleet), []byte(" {}")...), "grant_bad_shape"},
		"star": {sign(func() Grant {
			g := base
			g.Entitlements = []string{"svc.spawn", "*"}
			return g
		}(), fleet), "grant_star"},
		"slash write": {sign(func() Grant {
			g := base
			g.FileWrite = []string{"/"}
			return g
		}(), fleet), "grant_root_slash"},
		"actor": {sign(func() Grant {
			g := base
			g.Actor = "service:other"
			return g
		}(), fleet), "grant_bad_shape"},
	} {
		if _, err := VerifyGrant(c.doc, pub, 1_700_000_000); fail.Token(err) != c.want {
			t.Errorf("%s: %v, want %s", name, err, c.want)
		}
	}
	// A short key never verifies.
	if _, err := VerifyGrant(sign(base, fleet), pub[:31], 1_700_000_000); fail.Token(err) != "grant_bad_sig" {
		t.Fatalf("short key: %v", err)
	}
}
